   122  static int str_needs_quotes(const char* str, size_t len)
   123  {
   124      size_t i;
   125      for (i = 0; i < len; i++) {
   126          if (!allowed_unquoted_chars[(unsigned char)str[i]]) {
   127              return 1;
   128          }
   129      }
