   311  #define PO10i_LIMIT (INT64_MAX/10)
   312
   313  /* based on https://stackoverflow.com/a/4143288 */
   314  static int num_digits_i(int64_t i)
   315  {
   316      int n;
   317      int64_t po10;
   318      n=1;
   319      if (i < 0) {
   320          i = (i == INT64_MIN) ? INT64_MAX : -i;
   321          n++;
   322      }
   323      po10=10;
   324      while (i>=po10) {
   325          n++;
   326          if (po10 > PO10i_LIMIT) break;
   327          po10*=10;
   328      }
   329      return n;
   330  }
