   332  #define PO10u_LIMIT (UINT64_MAX/10)
   333
   334  /* based on https://stackoverflow.com/a/4143288 */
   335  static int num_digits_u(uint64_t i)
   336  {
   337      int n;
   338      uint64_t po10;
   339      n=1;
   340      po10=10;
   341      while (i>=po10) {
   342          n++;
   343          if (po10 > PO10u_LIMIT) break;
   344          po10*=10;
   345      }
   346      return n;
   347  }
