   584  static int node_from_openstep(parse_ctx ctx, plist_t *plist)
   585  {
   586      plist_t subnode = NULL;
   587      const char *p = NULL;
   588      while (ctx->pos < ctx->end && !ctx->err) {
   589          parse_skip_ws(ctx);
   590          if (ctx->pos >= ctx->end) {
   591              break;
   592          }
   593          plist_data_t data = plist_new_plist_data();
   594          if (*ctx->pos == '{') {
   595              data->type = PLIST_DICT;
   596              subnode = plist_new_node(data);
   597              ctx->pos++;
   598              parse_dict_data(ctx, subnode);
   599              if (ctx->err) {
   600                  goto err_out;
   601              }
   602              if (*ctx->pos != '}') {
   603                  PLIST_OSTEP_ERR("Missing terminating '}' at offset %ld\n", ctx->pos - ctx->start);
   604                  ctx->err++;
   605                  goto err_out;
   606              }
   607              ctx->pos++;
   608              *plist = subnode;
   609              parse_skip_ws(ctx);
   610              break;
   611          } else if (*ctx->pos == '(') {
   612              data->type = PLIST_ARRAY;
   613              subnode = plist_new_node(data);
   614              ctx->pos++;
   615              plist_t tmp = NULL;
   616              while (ctx->pos < ctx->end && !ctx->err) {
   617                  parse_skip_ws(ctx);
   618                  if (*ctx->pos == ')') {
   619                      break;
   620                  }
   621                  ctx->err = node_from_openstep(ctx, &tmp);
   622                  if (ctx->err != 0) {
   623                      break;
   624                  }
   625                  if (!tmp) {
   626                      ctx->err++;
   627                      break;
   628                  }
   629                  plist_array_append_item(subnode, tmp);
   630                  tmp = NULL;
   631                  parse_skip_ws(ctx);
   632                  if (*ctx->pos != ',') {
   633                      break;
   634                  }
   635                  ctx->pos++;
   636              }
   637              if (ctx->err) {
   638                  goto err_out;
   639              }
   640              if (*ctx->pos != ')') {
   641                  PLIST_OSTEP_ERR("Missing terminating ')' at offset %ld\n", ctx->pos - ctx->start);
   642                  ctx->err++;
   643                  goto err_out;
   644              }
   645              ctx->pos++;
   646              *plist = subnode;
   647              parse_skip_ws(ctx);
   648              break;
   649          } else if (*ctx->pos == '<') {
   650              data->type = PLIST_DATA;
   651              ctx->pos++;
   652              bytearray_t *bytes = byte_array_new(256);
   653              while (ctx->pos < ctx->end && !ctx->err) {
   654                  parse_skip_ws(ctx);
   655                  if (*ctx->pos == '>') {
   656                      break;
   657                  }
   658                  if (!isxdigit(*ctx->pos)) {
   659                      PLIST_OSTEP_ERR("Invalid byte group in data at offset %ld\n", ctx->pos - ctx->start);
   660                      ctx->err++;
   661                      break;
   662                  }
   663                  uint8_t b = HEX_DIGIT(*ctx->pos);
   664                  ctx->pos++;
   665                  if (ctx->pos >= ctx->end) {
   666                      PLIST_OSTEP_ERR("Unexpected end of data at offset %ld\n", ctx->pos - ctx->start);
   667                      ctx->err++;
   668                      break;
   669                  }
   670                  if (!isxdigit(*ctx->pos)) {
   671                      PLIST_OSTEP_ERR("Invalid byte group in data at offset %ld\n", ctx->pos - ctx->start);
   672                      ctx->err++;
   673                      break;
   674                  }
   675                  b = (b << 4) + HEX_DIGIT(*ctx->pos);
   676                  byte_array_append(bytes, &b, 1);
   677                  ctx->pos++;
   678              }
   679              if (ctx->err) {
   680                  byte_array_free(bytes);
   681                  plist_free_data(data);
   682                  goto err_out;
   683              }
   684              if (*ctx->pos != '>') {
   685                  byte_array_free(bytes);
   686                  plist_free_data(data);
   687                  PLIST_OSTEP_ERR("Missing terminating '>' at offset %ld\n", ctx->pos - ctx->start);
   688                  ctx->err++;
   689                  goto err_out;
   690              }
   691              ctx->pos++;
   692              data->buff = bytes->data;
   693              data->length = bytes->len;
   694              bytes->data = NULL;
   695              byte_array_free(bytes);
   696              *plist = plist_new_node(data);
   697              parse_skip_ws(ctx);
   698              break;
   699          } else if (*ctx->pos == '"' || *ctx->pos == '\'') {
   700              char c = *ctx->pos;
   701              ctx->pos++;
   702              p = ctx->pos;
   703              int num_escapes = 0;
   704              while (ctx->pos < ctx->end) {
   705                  if (*ctx->pos == '\\') {
   706                      num_escapes++;
   707                  }
   708                  if ((*ctx->pos == c) && (*(ctx->pos-1) != '\\')) {
   709                      break;
   710                  }
   711                  ctx->pos++;
   712              }
   713              if (*ctx->pos != c) {
   714                  plist_free_data(data);
   715                  PLIST_OSTEP_ERR("Missing closing quote (%c) at offset %ld\n", c, ctx->pos - ctx->start);
   716                  ctx->err++;
   717                  goto err_out;
   718              }
   719              size_t slen = ctx->pos - p;
   720              ctx->pos++; // skip the closing quote
   721              char* strbuf = malloc(slen+1);
   722              if (num_escapes > 0) {
   723                  size_t i = 0;
   724                  size_t o = 0;
   725                  while (i < slen) {
   726                      if (p[i] == '\\') {
   727                          /* handle escape sequence */
   728                          i++;
   729                          switch (p[i]) {
   730                              case '0':
   731                              case '1':
   732                              case '2':
   733                              case '3':
   734                              case '4':
   735                              case '5':
   736                              case '6':
   737                              case '7': {
   738                                  // max 3 digits octal
   739                                  unsigned char chr = 0;
   740                                  int maxd = 3;
   741                                  while ((i < slen) && (p[i] >= '0' && p[i] <= '7') && --maxd) {
   742                                      chr = (chr << 3) + p[i] - '0';
   743                                      i++;
   744                                  }
   745                                  strbuf[o++] = (char)chr;
   746                              }   break;
   747                              case 'U': {
   748                                  i++;
   749                                  // max 4 digits hex
   750                                  uint16_t wchr = 0;
   751                                  int maxd = 4;
   752                                  while ((i < slen) && isxdigit(p[i]) && maxd--) {
   753                                      wchr = (wchr << 4) + ((p[i] <= '9') ? (p[i] - '0') : ((p[i] <= 'F') ? (p[i] - 'A' + 10) : (p[i] - 'a' + 10)));
   754                                      i++;
   755                                  }
   756                                  if (wchr >= 0x800) {
   757                                      strbuf[o++] = (char)(0xE0 + ((wchr >> 12) & 0xF));
   758                                      strbuf[o++] = (char)(0x80 + ((wchr >> 6) & 0x3F));
   759                                      strbuf[o++] = (char)(0x80 + (wchr & 0x3F));
   760                                  } else if (wchr >= 0x80) {
   761                                      strbuf[o++] = (char)(0xC0 + ((wchr >> 6) & 0x1F));
   762                                      strbuf[o++] = (char)(0x80 + (wchr & 0x3F));
   763                                  } else {
   764                                      strbuf[o++] = (char)(wchr & 0x7F);
   765                                  }
   766                              }   break;
   767                              case 'a': strbuf[o++] = '\a'; i++; break;
   768                              case 'b': strbuf[o++] = '\b'; i++; break;
   769                              case 'f': strbuf[o++] = '\f'; i++; break;
   770                              case 'n': strbuf[o++] = '\n'; i++; break;
   771                              case 'r': strbuf[o++] = '\r'; i++; break;
   772                              case 't': strbuf[o++] = '\t'; i++; break;
   773                              case 'v': strbuf[o++] = '\v'; i++; break;
   774                              case '"': strbuf[o++] = '"';  i++; break;
   775                              case '\'': strbuf[o++] = '\''; i++; break;
   776                              default:
   777                                  break;
   778                          }
   779                      } else {
   780                          strbuf[o++] = p[i++];
   781                      }
   782                  }
   783                  strbuf[o] = '\0';
   784                  slen = o;
   785              } else {
   786                  strncpy(strbuf, p, slen);
   787                  strbuf[slen] = '\0';
   788              }
   789              data->type = PLIST_STRING;
   790              data->strval = strbuf;
   791              data->length = slen;
   792              *plist = plist_new_node(data);
   793              parse_skip_ws(ctx);
   794              break;
   795          } else {
   796              // unquoted string
   797              size_t slen = 0;
   798              parse_skip_ws(ctx);
   799              p = ctx->pos;
   800              while (ctx->pos < ctx->end) {
   801                  if (!allowed_unquoted_chars[(uint8_t)*ctx->pos]) {
   802                      break;
   803                  }
   804                  ctx->pos++;
   805              }
   806              slen = ctx->pos-p;
   807              if (slen > 0) {
   808                  data->type = PLIST_STRING;
   809                  data->strval = strndup(p, slen);
   810                  data->length = slen;
   811                  *plist = plist_new_node(data);
   812                  parse_skip_ws(ctx);
   813                  break;
   814              } else {
   815                  plist_free_data(data);
   816                  PLIST_OSTEP_ERR("Unexpected character when parsing unquoted string at offset %ld\n", ctx->pos - ctx->start);
   817                  ctx->err++;
   818                  break;
   819              }
   820          }
   821          ctx->pos++;
   822      }
   823
   824  err_out:
   825      if (ctx->err) {
   826          plist_free(subnode);
   827          plist_free(*plist);
   828          *plist = NULL;
   829          return PLIST_ERR_PARSE;
   830      }
   831      return PLIST_ERR_SUCCESS;
   832  }
