   834  PLIST_API int plist_from_openstep(const char *plist_ostep, uint32_t length, plist_t * plist)
   835  {
   836      if (!plist) {
   837          return PLIST_ERR_INVALID_ARG;
   838      }
   839      *plist = NULL;
   840      if (!plist_ostep || (length == 0)) {
   841          return PLIST_ERR_INVALID_ARG;
   842      }
   843
   844      struct _parse_ctx ctx = { plist_ostep, plist_ostep, plist_ostep + length, 0 };
   845
   846      int err = node_from_openstep(&ctx, plist);
   847      if (err == 0) {
   848          if (!*plist) {
   849              /* whitespace only file is considered an empty dictionary */
   850              *plist = plist_new_dict();
   851          } else if (ctx.pos < ctx.end && *ctx.pos == '=') {
   852              /* attempt to parse this as 'strings' data */
   853              plist_free(*plist);
   854              plist_t pl = plist_new_dict();
   855              ctx.pos = plist_ostep;
   856              parse_dict_data(&ctx, pl);
   857              if (ctx.err > 0) {
   858                  plist_free(pl);
   859                  PLIST_OSTEP_ERR("Failed to parse strings data\n");
   860                  err = PLIST_ERR_PARSE;
   861              } else {
   862                  *plist = pl;
   863              }
   864          }
   865      }
   866
   867      return err;
   868  }
