    76  int node_attach(node_t* parent, node_t* child) {
    77          if (!parent || !child) return -1;
    78          child->parent = parent;
    79          if(!parent->children) {
    80                  parent->children = node_list_create();
    81          }
    82          int res = node_list_add(parent->children, child);
    83          if (res == 0) {
    84                  parent->count++;
    85          }
    86          return res;
    87  }
