    89  int node_detach(node_t* parent, node_t* child) {
    90          if (!parent || !child) return -1;
    91          int node_index = node_list_remove(parent->children, child);
    92          if (node_index >= 0) {
    93                  parent->count--;
    94          }
    95          return node_index;
    96  }
